#include <stdio.h>

// ioctl encoding macros
#define _IOC_NRBITS     8
#define _IOC_TYPEBITS   8
#define _IOC_SIZEBITS   14
#define _IOC_DIRBITS    2

#define _IOC_NRSHIFT    0
#define _IOC_TYPESHIFT  (_IOC_NRSHIFT+_IOC_NRBITS)
#define _IOC_SIZESHIFT  (_IOC_TYPESHIFT+_IOC_TYPEBITS)
#define _IOC_DIRSHIFT   (_IOC_SIZESHIFT+_IOC_SIZEBITS)

#define _IOC_NONE       0U
#define _IOC_WRITE      1U
#define _IOC_READ       2U

#define _IOC(dir,type,nr,size) \
    (((dir)  << _IOC_DIRSHIFT) | \
     ((type) << _IOC_TYPESHIFT) | \
     ((nr)   << _IOC_NRSHIFT) | \
     ((size) << _IOC_SIZESHIFT))

#define _IO(type,nr)            _IOC(_IOC_NONE,(type),(nr),0)
#define _IOR(type,nr,size)      _IOC(_IOC_READ,(type),(nr),sizeof(size))
#define _IOW(type,nr,size)      _IOC(_IOC_WRITE,(type),(nr),sizeof(size))
#define _IOWR(type,nr,size)     _IOC(_IOC_READ|_IOC_WRITE,(type),(nr),sizeof(size))

#define PP_IOCTL 'p'

// Sizes for 64-bit
#define TIMEVAL_SIZE_64 16
#define INT_SIZE 4

// Sizes for 32-bit
#define TIMEVAL_SIZE_32 8

int main() {
    printf("# amd64 (64-bit) PPGETTIME/PPSETTIME:\n");
    printf("PPGETTIME_64 = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x95, TIMEVAL_SIZE_64));
    printf("PPSETTIME_64 = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x96, TIMEVAL_SIZE_64));

    printf("\n# 386 (32-bit) PPGETTIME/PPSETTIME:\n");
    printf("PPGETTIME_32 = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x95, TIMEVAL_SIZE_32));
    printf("PPSETTIME_32 = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x96, TIMEVAL_SIZE_32));

    return 0;
}
EOF
