#include <stdio.h>

// ioctl encoding macros for standard (x86, arm, etc)
#define _IOC_NRBITS     8
#define _IOC_TYPEBITS   8
#define _IOC_SIZEBITS   14
#define _IOC_DIRBITS    2

#define _IOC_NRSHIFT    0
#define _IOC_TYPESHIFT  8
#define _IOC_SIZESHIFT  16
#define _IOC_DIRSHIFT   30

#define _IOC_NONE       0U
#define _IOC_WRITE      1U
#define _IOC_READ       2U

// For mips/powerpc, read/write are swapped
#define _IOC_MIPS_WRITE  2U
#define _IOC_MIPS_READ   1U

#define _IOC(dir,type,nr,size) \
    (((dir)  << _IOC_DIRSHIFT) | \
     ((type) << _IOC_TYPESHIFT) | \
     ((nr)   << _IOC_NRSHIFT) | \
     ((size) << _IOC_SIZESHIFT))

#define PP_IOCTL 'p'

int main() {
    printf("# Standard (x86/arm) ioctl values:\n");

    // _IO ioctls (no data)
    printf("PPCLAIM = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8b, 0));
    printf("PPRELEASE = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8c, 0));
    printf("PPYIELD = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8d, 0));
    printf("PPEXCL = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8f, 0));

    // _IOR (read from kernel) ioctls
    printf("PPRSTATUS = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x81, 1));
    printf("PPRCONTROL = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x83, 1));
    printf("PPRDATA = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x85, 1));
    printf("PPCLRIRQ = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x93, 4));
    printf("PPGETMODES = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x97, 4));
    printf("PPGETMODE = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x98, 4));
    printf("PPGETPHASE = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x99, 4));
    printf("PPGETFLAGS = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x9a, 4));
    printf("PPGETTIME_64 = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x95, 16));
    printf("PPGETTIME_32 = %u\n", _IOC(_IOC_READ, PP_IOCTL, 0x95, 8));

    // _IOW (write to kernel) ioctls
    printf("PPSETMODE = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x80, 4));
    printf("PPWCONTROL = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x84, 1));
    printf("PPFCONTROL = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x8e, 2));
    printf("PPWDATA = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x86, 1));
    printf("PPDATADIR = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x90, 4));
    printf("PPNEGOT = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x91, 4));
    printf("PPWCTLONIRQ = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x92, 1));
    printf("PPSETPHASE = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x94, 4));
    printf("PPSETFLAGS = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x9b, 4));
    printf("PPSETTIME_64 = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x96, 16));
    printf("PPSETTIME_32 = %u\n", _IOC(_IOC_WRITE, PP_IOCTL, 0x96, 8));

    printf("\n# mips64le/ppc64le ioctl values (read/write swapped):\n");

    // _IO ioctls (no data) - same
    printf("PPCLAIM_MIPS = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8b, 0));
    printf("PPRELEASE_MIPS = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8c, 0));
    printf("PPYIELD_MIPS = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8d, 0));
    printf("PPEXCL_MIPS = %u\n", _IOC(_IOC_NONE, PP_IOCTL, 0x8f, 0));

    // _IOR becomes _MIPS_READ
    printf("PPRSTATUS_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x81, 1));
    printf("PPRCONTROL_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x83, 1));
    printf("PPRDATA_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x85, 1));
    printf("PPCLRIRQ_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x93, 4));
    printf("PPGETMODES_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x97, 4));
    printf("PPGETMODE_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x98, 4));
    printf("PPGETPHASE_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x99, 4));
    printf("PPGETFLAGS_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x9a, 4));
    printf("PPGETTIME_64_MIPS = %u\n", _IOC(_IOC_MIPS_READ, PP_IOCTL, 0x95, 16));

    // _IOW becomes _MIPS_WRITE
    printf("PPSETMODE_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x80, 4));
    printf("PPWCONTROL_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x84, 1));
    printf("PPFCONTROL_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x8e, 2));
    printf("PPWDATA_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x86, 1));
    printf("PPDATADIR_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x90, 4));
    printf("PPNEGOT_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x91, 4));
    printf("PPWCTLONIRQ_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x92, 1));
    printf("PPSETPHASE_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x94, 4));
    printf("PPSETFLAGS_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x9b, 4));
    printf("PPSETTIME_64_MIPS = %u\n", _IOC(_IOC_MIPS_WRITE, PP_IOCTL, 0x96, 16));

    return 0;
}
EOF
